const copy={en:{title:'Custody Consulting — Bitcoin, in your hands.',navServices:'Services',navApproach:'Our approach',eyebrow:'Bitcoin self-custody · Europe',headline:'Your bitcoin.<br>Your keys.<br><em>Your peace of mind.</em>',intro:'A considered approach to holding your own bitcoin. Personal guidance for individuals, families and businesses across Europe — in English and Polish.',cta:'Discuss your custody setup',heroNote:'A clear conversation. A practical next step.',artNote:'OWNERSHIP STARTS WITH YOUR KEYS',trust1:'Bitcoin only',trust2:'English & Polish',trust3:'You remain in control',servicesLabel:'01 / HOW WE HELP',servicesTitle:'Confidence, built on a plan.',servicesIntro:'From your first hardware wallet to a more resilient custody strategy. Start with what you need, and understand every decision.',services:[['Self-custody foundations','Understand wallet options, set up a hardware wallet and build a repeatable process for receiving and sending bitcoin.','Wallet selection · Guided setup'],['Custody review & design','Review your existing approach, explore single-signature and multisignature trade-offs, and plan backups and recovery.','Risk review · Recovery planning'],['Family & business continuity','Build clear operational instructions and an emergency access plan. Coordinate inheritance questions with your legal advisers.','Documentation · Continuity']],approachLabel:'02 / THE APPROACH',approachTitle:'Good custody is a process.<br>Not just a device.',principle:'The goal is a setup you understand, can use independently, and can maintain as your life changes.',steps:[['Understand your situation','Discuss your experience, responsibilities and priorities without sharing balances, keys or recovery words.'],['Design a practical setup','Choose an approach with clear trade-offs, suitable backups and a documented recovery process.'],['Practise, then maintain','Use a controlled test to practise the workflow and agree when to revisit your plan.']],audienceLabel:'03 / WHO IT’S FOR',audienceTitle:'Personal guidance.<br>A European perspective.',audienceIntro:'Conversations in English or Polish, with space for the questions that matter to you.',audiences:[['Individuals','Move from uncertainty to a custody approach you can explain and operate.'],['Families','Make continuity and emergency access part of the plan from the start.'],['Businesses','Define responsibilities, approval procedures and documentation for bitcoin holdings.']],faqLabel:'04 / YOUR QUESTIONS',faqTitle:'Clarity before complexity.',questions:[['Will you hold my bitcoin or my keys?','The proposed service is education and implementation guidance. You retain control. Never share a seed phrase, private key or wallet backup with a consultant.'],['Do I need technical experience?','No. The starting point is your current understanding. More advanced arrangements can be explored when there is a clear reason for them.'],['Can we work in Polish?','Yes. This website and the proposed consulting service are designed for both English-speaking and Polish-speaking clients in Europe.'],['Is multisignature always the best choice?','No. It can reduce some risks while adding operational complexity. The right approach depends on who must operate and recover the setup.'],['Does this include legal, tax or investment advice?','The proposed scope is custody education and operational planning. Legal, tax and investment questions should be addressed with appropriately qualified advisers in your jurisdiction.']],contactLabel:'LET’S START WITH CLARITY',contactTitle:'Take the next step towards<br>owning your bitcoin.',contactIntro:'Discuss where you are today, what concerns you, and what a workable custody plan could look like.',draftTitle:'Consultation booking is being prepared',draftText:'This is a first website draft. A verified contact address or booking calendar must be connected before consultation requests can be accepted. Please do not enter or share wallet secrets.',footerNote:'Built for Europe. Available in English & Polish.',disclaimer:'Draft service proposition. No client assets or keys are held. Educational and operational guidance only; no financial, investment, legal or tax advice. Self-custody carries risks and requires personal responsibility.'},pl:{title:'Custody Consulting — Twój bitcoin, w Twoich rękach.',navServices:'Usługi',navApproach:'Jak pracujemy',eyebrow:'Samodzielna piecza nad bitcoinem · Europa',headline:'Twój bitcoin.<br>Twoje klucze.<br><em>Twój spokój.</em>',intro:'Przemyślane podejście do przechowywania bitcoina. Indywidualne wsparcie dla osób prywatnych, rodzin i firm w Europie — po polsku i angielsku.',cta:'Porozmawiajmy o Twoim planie',heroNote:'Jasna rozmowa. Konkretny kolejny krok.',artNote:'WŁASNOŚĆ ZACZYNA SIĘ OD TWOICH KLUCZY',trust1:'Tylko Bitcoin',trust2:'Po polsku i angielsku',trust3:'Zachowujesz kontrolę',servicesLabel:'01 / JAK POMAGAMY',servicesTitle:'Pewność oparta na planie.',servicesIntro:'Od pierwszego portfela sprzętowego po bardziej odporny system przechowywania. Zacznij od swoich potrzeb i zrozum każdą decyzję.',services:[['Podstawy samodzielnej pieczy','Poznaj rodzaje portfeli, skonfiguruj portfel sprzętowy i wypracuj powtarzalny sposób odbierania oraz wysyłania bitcoina.','Wybór portfela · Konfiguracja'],['Przegląd i projekt systemu','Przeanalizuj obecne rozwiązanie, poznaj zalety i ograniczenia pojedynczego podpisu oraz multisig. Zaplanuj kopie zapasowe i odzyskiwanie.','Analiza ryzyka · Odzyskiwanie'],['Ciągłość dla rodziny i firmy','Przygotuj czytelne instrukcje oraz plan dostępu awaryjnego. Kwestie dziedziczenia skoordynuj ze swoim prawnikiem.','Dokumentacja · Ciągłość']],approachLabel:'02 / JAK PRACUJEMY',approachTitle:'Bezpieczna piecza to proces.<br>Nie tylko urządzenie.',principle:'Celem jest rozwiązanie, które rozumiesz, potrafisz samodzielnie obsługiwać i dostosowywać do zmian w swoim życiu.',steps:[['Poznajemy Twoją sytuację','Rozmawiamy o doświadczeniu, obowiązkach i priorytetach, bez ujawniania salda, kluczy ani frazy odzyskiwania.'],['Tworzymy praktyczny plan','Wybieramy rozwiązanie ze zrozumiałymi kompromisami, odpowiednimi kopiami zapasowymi i opisaną procedurą odzyskiwania.'],['Ćwiczymy i aktualizujemy','W kontrolowanym teście przećwiczysz procedury. Ustalimy też, kiedy warto wrócić do planu.']],audienceLabel:'03 / DLA KOGO',audienceTitle:'Indywidualne wsparcie.<br>Europejska perspektywa.',audienceIntro:'Rozmowy po polsku lub angielsku, z przestrzenią na pytania, które są dla Ciebie ważne.',audiences:[['Osoby prywatne','Zastąp niepewność rozwiązaniem, które potrafisz wyjaśnić i obsługiwać.'],['Rodziny','Uwzględnij ciągłość i dostęp awaryjny już na etapie planowania.'],['Firmy','Określ odpowiedzialność, zasady zatwierdzania transakcji i dokumentację dotyczącą bitcoina.']],faqLabel:'04 / TWOJE PYTANIA',faqTitle:'Najpierw zrozumienie.',questions:[['Czy będziecie przechowywać moje bitcoiny lub klucze?','Proponowana usługa obejmuje edukację i wsparcie we wdrożeniu. Zachowujesz kontrolę. Nigdy nie udostępniaj konsultantowi frazy odzyskiwania, klucza prywatnego ani kopii portfela.'],['Czy potrzebuję wiedzy technicznej?','Nie. Punktem wyjścia jest Twój obecny poziom wiedzy. Bardziej zaawansowane rozwiązania warto rozważać wtedy, gdy istnieje konkretna potrzeba.'],['Czy możemy pracować po polsku?','Tak. Ta strona i proponowana usługa konsultingowa są przeznaczone dla klientów polskojęzycznych i anglojęzycznych w Europie.'],['Czy multisig jest zawsze najlepszym wyborem?','Nie. Może ograniczać pewne ryzyka, jednocześnie zwiększając złożoność obsługi. Wybór zależy od tego, kto będzie obsługiwał system i odzyskiwał dostęp.'],['Czy usługa obejmuje porady prawne, podatkowe lub inwestycyjne?','Proponowany zakres to edukacja i planowanie operacyjne. Kwestie prawne, podatkowe i inwestycyjne należy omówić z odpowiednio wykwalifikowanymi doradcami w swojej jurysdykcji.']],contactLabel:'ZACZNIJMY OD JASNEGO PLANU',contactTitle:'Kolejny krok do pełnej<br>kontroli nad bitcoinem.',contactIntro:'Porozmawiajmy o Twojej obecnej sytuacji, obawach i praktycznym planie przechowywania.',draftTitle:'Rezerwacja konsultacji jest w przygotowaniu',draftText:'To pierwsza wersja strony. Zanim będzie można przyjmować zgłoszenia, należy podłączyć zweryfikowany adres kontaktowy lub kalendarz rezerwacji. Nie podawaj żadnych poufnych danych portfela.',footerNote:'Dla Europy. Po polsku i angielsku.',disclaimer:'Wstępna propozycja usług. Nie przechowujemy aktywów ani kluczy klientów. Wyłącznie edukacja i wsparcie operacyjne, bez porad finansowych, inwestycyjnych, prawnych i podatkowych. Samodzielna piecza wiąże się z ryzykiem i osobistą odpowiedzialnością.'}};
const lang=new URLSearchParams(location.search).get('lang')==='pl'?'pl':'en',c=copy[lang];document.documentElement.lang=lang;document.title=c.title;document.querySelector('meta[name="description"]').content=c.intro;document.getElementById(lang).classList.add('active');document.getElementById(lang).setAttribute('aria-current','true');document.querySelectorAll('[data-i]').forEach(el=>el.innerHTML=c[el.dataset.i]);document.getElementById('serviceCards').innerHTML=c.services.map((s,i)=>`<article class="card"><span class="num">0${i+1} /</span><h3>${s[0]}</h3><p>${s[1]}</p><div class="tags">${s[2]}</div></article>`).join('');document.getElementById('steps').innerHTML=c.steps.map((s,i)=>`<article><b>0${i+1}</b><div><h3>${s[0]}</h3><p>${s[1]}</p></div></article>`).join('');document.getElementById('audiences').innerHTML=c.audiences.map(s=>`<div><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('');document.getElementById('questions').innerHTML=c.questions.map(s=>`<details><summary>${s[0]}</summary><p>${s[1]}</p></details>`).join('');document.getElementById('contactButton').onclick=()=>{const p=document.getElementById('contactPanel');p.hidden=!p.hidden;document.getElementById('contactButton').setAttribute('aria-expanded',String(!p.hidden));};
